import React, { useEffect, useState } from 'react';
import { itemsAPI, salesAPI, formatCurrency } from '../api';

function Reports({ showToast }) {
  const [items, setItems] = useState([]);
  const [sales, setSales] = useState([]);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    loadReports();
  }, []);

  const loadReports = async () => {
    try {
      setLoading(true);
      const [itemsData, salesData] = await Promise.all([
        itemsAPI.getAll(),
        salesAPI.getAll(),
      ]);
      setItems(itemsData.data || []);
      setSales(salesData.data || []);
    } catch (error) {
      showToast(`Failed to load reports: ${error.message}`, 'error');
    } finally {
      setLoading(false);
    }
  };

  // Calculate low stock items
  const lowStockItems = items.filter((item) => item.quantity < 10);

  // Calculate sales summary
  const totalRevenue = sales.reduce((sum, sale) => sum + sale.totalAmount, 0);
  const totalItemsSold = sales.reduce((sum, sale) => sum + sale.quantitySold, 0);
  const avgOrderValue = sales.length > 0 ? totalRevenue / sales.length : 0;

  // Calculate top selling items
  const itemSales = {};
  sales.forEach((sale) => {
    if (!itemSales[sale.itemName]) {
      itemSales[sale.itemName] = {
        name: sale.itemName,
        quantity: 0,
        revenue: 0,
      };
    }
    itemSales[sale.itemName].quantity += sale.quantitySold;
    itemSales[sale.itemName].revenue += sale.totalAmount;
  });
  const topItems = Object.values(itemSales)
    .sort((a, b) => b.quantity - a.quantity)
    .slice(0, 5);

  // Calculate category breakdown
  const categories = {};
  items.forEach((item) => {
    const category = item.category || 'Uncategorized';
    if (!categories[category]) {
      categories[category] = {
        count: 0,
        value: 0,
        quantity: 0,
      };
    }
    categories[category].count++;
    categories[category].value += item.price * item.quantity;
    categories[category].quantity += item.quantity;
  });

  if (loading) {
    return (
      <div className="loading-container">
        <div className="loading-spinner"></div>
        <p className="loading-text">Loading reports...</p>
      </div>
    );
  }

  return (
    <div className="container">
      <div className="section-header">
        <h1 className="section-title">Reports & Analytics</h1>
        <button className="btn btn-primary" onClick={loadReports}>
          🔄 Refresh Reports
        </button>
      </div>

      <div style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fit, minmax(300px, 1fr))', gap: '1.5rem' }}>
        {/* Low Stock Alert */}
        <div className="card">
          <h3 style={{ fontSize: '1.25rem', marginBottom: '1rem', color: 'var(--danger)' }}>
            ⚠️ Low Stock Alert
          </h3>
          {lowStockItems.length === 0 ? (
            <p style={{ color: 'var(--secondary)' }}>✅ All items have sufficient stock!</p>
          ) : (
            <div style={{ display: 'grid', gap: '0.75rem' }}>
              {lowStockItems.map((item) => (
                <div
                  key={item._id}
                  style={{
                    padding: '0.75rem',
                    background: 'var(--light-gray)',
                    borderRadius: '8px',
                    display: 'flex',
                    justifyContent: 'space-between',
                    alignItems: 'center',
                  }}
                >
                  <div>
                    <strong>{item.name}</strong>
                    <p style={{ margin: '0.25rem 0 0', fontSize: '0.875rem', color: 'var(--gray)' }}>
                      {item.category}
                    </p>
                  </div>
                  <span className={`badge ${item.quantity === 0 ? 'badge-danger' : 'badge-warning'}`}>
                    {item.quantity} left
                  </span>
                </div>
              ))}
            </div>
          )}
        </div>

        {/* Sales Summary */}
        <div className="card">
          <h3 style={{ fontSize: '1.25rem', marginBottom: '1rem', color: 'var(--primary)' }}>
            📊 Sales Summary
          </h3>
          {sales.length === 0 ? (
            <p style={{ color: 'var(--gray)' }}>No sales recorded yet.</p>
          ) : (
            <div style={{ display: 'grid', gap: '0.75rem' }}>
              <div
                style={{
                  padding: '0.75rem',
                  background: 'var(--light-gray)',
                  borderRadius: '8px',
                }}
              >
                <strong style={{ color: 'var(--primary)' }}>Total Revenue</strong>
                <p style={{ margin: '0.25rem 0 0', fontSize: '1.5rem', fontWeight: '700' }}>
                  {formatCurrency(totalRevenue)}
                </p>
              </div>
              <div
                style={{
                  padding: '0.75rem',
                  background: 'var(--light-gray)',
                  borderRadius: '8px',
                }}
              >
                <strong style={{ color: 'var(--primary)' }}>Total Orders</strong>
                <p style={{ margin: '0.25rem 0 0', fontSize: '1.5rem', fontWeight: '700' }}>
                  {sales.length}
                </p>
              </div>
              <div
                style={{
                  padding: '0.75rem',
                  background: 'var(--light-gray)',
                  borderRadius: '8px',
                }}
              >
                <strong style={{ color: 'var(--primary)' }}>Items Sold</strong>
                <p style={{ margin: '0.25rem 0 0', fontSize: '1.5rem', fontWeight: '700' }}>
                  {totalItemsSold}
                </p>
              </div>
              <div
                style={{
                  padding: '0.75rem',
                  background: 'var(--light-gray)',
                  borderRadius: '8px',
                }}
              >
                <strong style={{ color: 'var(--primary)' }}>Avg. Order Value</strong>
                <p style={{ margin: '0.25rem 0 0', fontSize: '1.5rem', fontWeight: '700' }}>
                  {formatCurrency(avgOrderValue)}
                </p>
              </div>
            </div>
          )}
        </div>

        {/* Top Selling Items */}
        <div className="card">
          <h3 style={{ fontSize: '1.25rem', marginBottom: '1rem', color: 'var(--secondary)' }}>
            🏆 Top Selling Items
          </h3>
          {topItems.length === 0 ? (
            <p style={{ color: 'var(--gray)' }}>No sales data available.</p>
          ) : (
            <div style={{ display: 'grid', gap: '0.75rem' }}>
              {topItems.map((item, index) => (
                <div
                  key={item.name}
                  style={{
                    padding: '0.75rem',
                    background: 'var(--light-gray)',
                    borderRadius: '8px',
                  }}
                >
                  <div style={{ display: 'flex', alignItems: 'center', gap: '0.5rem' }}>
                    <span
                      style={{
                        fontSize: '1.5rem',
                        fontWeight: '700',
                        color: 'var(--primary)',
                      }}
                    >
                      #{index + 1}
                    </span>
                    <div style={{ flex: 1 }}>
                      <strong>{item.name}</strong>
                      <p style={{ margin: '0.25rem 0 0', fontSize: '0.875rem', color: 'var(--gray)' }}>
                        Sold: {item.quantity} units • Revenue: {formatCurrency(item.revenue)}
                      </p>
                    </div>
                  </div>
                </div>
              ))}
            </div>
          )}
        </div>

        {/* Category Breakdown */}
        <div className="card">
          <h3 style={{ fontSize: '1.25rem', marginBottom: '1rem', color: 'var(--warning)' }}>
            📁 Category Breakdown
          </h3>
          {items.length === 0 ? (
            <p style={{ color: 'var(--gray)' }}>No items available.</p>
          ) : (
            <div style={{ display: 'grid', gap: '0.75rem' }}>
              {Object.entries(categories).map(([category, data]) => (
                <div
                  key={category}
                  style={{
                    padding: '0.75rem',
                    background: 'var(--light-gray)',
                    borderRadius: '8px',
                  }}
                >
                  <strong style={{ fontSize: '1.1rem' }}>{category}</strong>
                  <div style={{ marginTop: '0.5rem', fontSize: '0.875rem', color: 'var(--gray)' }}>
                    <p style={{ margin: '0.25rem 0' }}>
                      Items: <strong>{data.count}</strong> • Stock: <strong>{data.quantity}</strong>
                    </p>
                    <p style={{ margin: '0.25rem 0' }}>
                      Value: <strong style={{ color: 'var(--primary)' }}>{formatCurrency(data.value)}</strong>
                    </p>
                  </div>
                </div>
              ))}
            </div>
          )}
        </div>
      </div>
    </div>
  );
}

export default Reports;
